using System;using System.IO;using System.Linq;using System.Diagnostics;using UnityEditor;using UnityEngine;
namespace RebirthEntityStudio {
 [Serializable] public sealed class BodyImageConfiguration {public string python,model,modelSha256;}
 public sealed class RebirthBodyImageJob:IDisposable {
  [Serializable] sealed class Request {public string template,templateHash,extension,extensionHash,reference,referenceHash,segmentationModel,segmentationModelSha256,authoredSurface,authoredSurfaceSha256;public BodyRecipe recipe;}
  [Serializable] sealed class WidthReport {public bool accepted;public string reason;}
  [Serializable] sealed class Report {public string templateHash,extensionHash,referenceSha256,authoredBodyHash,authoredSurfaceSha256;public bool accepted,authoredSurfaceFrames;public WidthReport silhouette;}
  bool surfaceFrames;string authoredGuid="",authoredHash="",samplingHash="";
  Process process;bool started;string folder,errors="",referenceHash,templateHash,referenceGuid;BodyTemplate template;DateTime start=DateTime.UtcNow;
  public bool Finished{get;private set;}public string Error{get;private set;}public string Status{get;private set;}="Preparing body reference";public float Progress{get;private set;}public BodyRecipe Candidate{get;private set;}public double ElapsedSeconds=>(DateTime.UtcNow-start).TotalSeconds;
  public static string ConfigurationPath=>Path.GetFullPath("ProjectSettings/RebirthBodyImage.json");
  public int? WorkerProcessId{get{try{return process==null?null:(int?)process.Id;}catch(InvalidOperationException){return null;}}}
  public static BodyImageConfiguration Configuration(){if(File.Exists(ConfigurationPath))return JsonUtility.FromJson<BodyImageConfiguration>(File.ReadAllText(ConfigurationPath));var face=RebirthFaceImageJob.ReadConfiguration();return new BodyImageConfiguration{python=face.python,model=string.IsNullOrEmpty(face.model)?"":Path.GetFullPath(Path.Combine(Path.GetDirectoryName(face.model),"../BodyImage/pose_landmarker_full.task")),modelSha256="5134a3aad27a58b93da0088d431f366da362b44e3ccfbe3462b3827a839011b1"};}
  static string Hash(string path){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
  static string Quote(string value){if(string.IsNullOrEmpty(value)||value.IndexOfAny(new[]{'"','\r','\n'})>=0)throw new ArgumentException("Invalid body image path");return "\""+value+"\"";}
  public RebirthBodyImageJob(BodyTemplate data,BodyRecipe recipe,string imageGuid){try{
   template=data;templateHash=data.contentHash;referenceGuid=imageGuid;var config=Configuration();string reference=Path.GetFullPath(AssetDatabase.GUIDToAssetPath(imageGuid));foreach(string path in new[]{reference,config.python,config.model})if(!File.Exists(path))throw new FileNotFoundException("Configure body image analysis first: "+path);
   if(Hash(config.model)!=config.modelSha256)throw new InvalidDataException("Body pose model hash differs from configuration");
   string backend=AssetDatabase.FindAssets("body_image_backend").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/body_image_backend.py",StringComparison.Ordinal));string source=AssetDatabase.FindAssets("BodyTemplate t:TextAsset").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/BodyGeneratorData/BodyTemplate.json",StringComparison.Ordinal));if(backend==null||source==null)throw new FileNotFoundException("Body image worker or template missing");
   referenceHash=Hash(reference);folder=Path.GetFullPath("Library/RebirthBodyImage/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var original=JsonUtility.FromJson<BodyRecipe>(JsonUtility.ToJson(recipe));original.referenceGuid=imageGuid;original.Validate(template);surfaceFrames=original.authoredSurfaceFrames;
   string sampling="";if(!string.IsNullOrEmpty(original.authoredBodyGuid)){Status="Preparing authored body surface sampling";var surface=RebirthAuthoredBody.ImageSampling(template,original);sampling=Path.Combine(folder,"AuthoredSurface.json");File.WriteAllText(sampling,JsonUtility.ToJson(surface));samplingHash=Hash(sampling);authoredGuid=original.authoredBodyGuid;authoredHash=original.authoredBodyHash;}
   File.WriteAllText(Path.Combine(folder,"request.json"),JsonUtility.ToJson(new Request{authoredSurface=sampling,authoredSurfaceSha256=samplingHash,template=Path.GetFullPath(source),templateHash=templateHash,extension=string.IsNullOrEmpty(template.extensionHash)?"":Path.GetFullPath(RebirthBodyComposition.DataPath()),extensionHash=template.extensionHash,reference=reference,referenceHash=referenceHash,segmentationModel=RebirthFaceImageJob.ReadConfiguration().segmentationModel,segmentationModelSha256=RebirthFaceImageJob.ReadConfiguration().segmentationModelSha256,recipe=original},true));
   var info=new ProcessStartInfo(config.python,Quote(Path.GetFullPath(backend))+" --job "+Quote(folder)+" --model "+Quote(config.model)+" --model-sha256 "+Quote(config.modelSha256)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};info.EnvironmentVariables["PYTHONDONTWRITEBYTECODE"]="1";process=new Process{StartInfo=info};process.OutputDataReceived+=(s,e)=>{};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(this){errors+=e.Data+"\n";if(errors.Length>12000)errors=errors.Substring(errors.Length-12000);}};process.Start();started=true;process.BeginOutputReadLine();process.BeginErrorReadLine();
  }catch{Dispose();throw;}}
  public void Poll(){if(Finished)return;try{
   string path=Path.Combine(folder,"progress.json");try{if(File.Exists(path)){FaceImageProgress state;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream))state=JsonUtility.FromJson<FaceImageProgress>(reader.ReadToEnd());if(state!=null){Progress=Mathf.Max(Progress,Mathf.Clamp01(state.progress));Status=state.message;}}}catch(IOException){}
   if(!process.HasExited){if(ElapsedSeconds>120)throw new TimeoutException("Body image fitting exceeded two minutes; current body retained");return;}process.WaitForExit();if(process.ExitCode!=0){File.WriteAllText(Path.Combine(folder,"worker-error.log"),errors);string last=errors.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).LastOrDefault()??"Worker failed";throw new InvalidOperationException("Body reference fitting failed: "+last+". Details: "+Path.Combine(folder,"worker-error.log"));}
   var report=JsonUtility.FromJson<Report>(File.ReadAllText(Path.Combine(folder,"report.json")));if(report.templateHash!=templateHash||report.extensionHash!=template.extensionHash||report.referenceSha256!=referenceHash)throw new InvalidDataException("Body result provenance differs from the request");if(Hash(AssetDatabase.GUIDToAssetPath(referenceGuid))!=referenceHash)throw new InvalidDataException("Body reference changed during analysis");
   if((report.authoredBodyHash??"")!=authoredHash||(report.authoredSurfaceSha256??"")!=samplingHash)throw new InvalidDataException("Authored body fit provenance differs from request");
   if(report.authoredSurfaceFrames!=surfaceFrames)throw new InvalidDataException("Image fit used a different authored surface deformation mode");
   if(!string.IsNullOrEmpty(authoredGuid)&&Hash(AssetDatabase.GUIDToAssetPath(authoredGuid))!=authoredHash)throw new InvalidDataException("Authored body foundation changed during image fitting");
   Candidate=JsonUtility.FromJson<BodyRecipe>(File.ReadAllText(Path.Combine(folder,"BodySettings.json")));Candidate.Validate(template);Candidate.referenceGuid=referenceGuid;Candidate.generationReportGuid="";if(Candidate.authoredSurfaceFrames!=surfaceFrames)throw new InvalidDataException("Image fit changed surface deformation mode");if((Candidate.authoredBodyGuid??"")!=authoredGuid||(Candidate.authoredBodyHash??"")!=authoredHash)throw new InvalidDataException("Image fit changed the selected authored foundation");
   string target="Assets/BodyGeneratorGenerated/Reference_"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(target);foreach(string file in new[]{"report.json","PoseObservations.json","PersonMask.png","BodySilhouetteReport.json","AppearanceObservations.json","SemanticCategories.png","body-skinConfidence.png"}){if(File.Exists(Path.Combine(folder,file))){File.Copy(Path.Combine(folder,file),target+"/"+file);AssetDatabase.ImportAsset(target+"/"+file);}}
   Candidate.bodyImageReportGuid=AssetDatabase.AssetPathToGUID(target+"/report.json");File.WriteAllText(target+"/BodySettings.json",JsonUtility.ToJson(Candidate,true));AssetDatabase.ImportAsset(target+"/BodySettings.json");Progress=1;Status=report.silhouette!=null&&report.silhouette.accepted?"Estimated body proportions and exposed widths ready. Skin and hidden anatomy unchanged.":(report.accepted?"Estimated pose proportions ready. ":"Proportions retained. ")+(report.silhouette?.reason??"No visible width observations.");Finished=true;
  }catch(Exception e){Error=e.Message;Status=Error;Finished=true;Dispose();}}
  public void Dispose(){if(process!=null){try{if(started&&!process.HasExited)process.Kill();}finally{process.Dispose();process=null;}}}
 }
}

